/** The password must have been re-entered recently (spec 19: re-authenticate before deleting). */
export function recentlyAuthenticated(
  lastSignInAt: string | null | undefined,
  nowMs: number,
): boolean {
  if (!lastSignInAt) return false;
  const t = Date.parse(lastSignInAt);
  return Number.isFinite(t) && nowMs - t <= REAUTH_MINUTES * 60_000 && t <= nowMs + 60_000;
}
